export interface Permit {
  ownerId: string;
  zones: readonly string[];
}

export interface Route {
  id: string;
  zone: string;
  priority: number;
  enabled: boolean;
}

export class RouteResolutionError extends Error {
  constructor(public readonly ownerId: string) {
    super(`No route for ${ownerId}`);
    this.name = "RouteResolutionError";
  }
}

export function resolveRoute(permit: Permit, routes: readonly Route[]): Route {
  const ownerId = permit.ownerId.trim();
  const zones = permit.zones.map((zone) => zone.trim());
  if (ownerId.length === 0 || zones.some((zone) => zone.length === 0)) {
    throw new RangeError("Permit fields must be non-blank");
  }
  const normalized = routes.map((route) => {
    const id = route.id.trim();
    const zone = route.zone.trim();
    if (id.length === 0 || zone.length === 0 || !Number.isFinite(route.priority) || !Number.isInteger(route.priority)) {
      throw new RangeError("Invalid route");
    }
    return { id, zone, priority: route.priority, enabled: route.enabled };
  });
  if (new Set(normalized.map((route) => route.id)).size !== normalized.length) {
    throw new Error("Duplicate route ID");
  }
  let best: Route | undefined;
  for (const route of normalized) {
    if (route.enabled && zones.includes(route.zone) && (best === undefined || route.priority > best.priority)) {
      best = route;
    }
  }
  if (best === undefined) throw new RouteResolutionError(ownerId);
  return { ...best };
}

