import { RouteResolutionError, resolveRoute } from "./solution";
import type { Permit, Route } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function expectRangeError(action: () => void): void {
  let thrown: unknown;
  try { action(); } catch (error) { thrown = error; }
  assert(thrown instanceof RangeError, "expected RangeError");
}
function expectErrorMessage(action: () => void, message: string): void {
  let thrown: unknown;
  try { action(); } catch (error) { thrown = error; }
  assert(thrown instanceof Error, "expected Error");
  if (errorMessage(thrown) !== message) throw new Error(`expected ${message}, got ${errorMessage(thrown)}`);
}
function errorMessage(error: Error): string { return error.message; }
function expectNoRoute(action: () => void, ownerId: string): void {
  let thrown: unknown;
  try { action(); } catch (error) { thrown = error; }
  assert(thrown instanceof RouteResolutionError, "expected RouteResolutionError");
  assert(thrown instanceof Error, "RouteResolutionError must extend Error");
  if (thrown.message !== `No route for ${ownerId}` || thrown.ownerId !== ownerId) throw new Error("no-route error details incorrect");
}

const zones = [" north ", "south"];
const permit: Permit = { ownerId: " owner-1 ", zones };
const routes: Route[] = [
  { id: " early ", zone: "north", priority: 2, enabled: true },
  { id: "disabled", zone: "north", priority: 0, enabled: false },
  { id: "other", zone: "east", priority: -10, enabled: true },
  { id: " winner ", zone: " south ", priority: 1, enabled: true },
  { id: "tie", zone: "south", priority: 1, enabled: true },
];
const resolved = resolveRoute(permit, routes);
if (resolved.id !== "winner" || resolved.zone !== "south" || resolved.priority !== 1 || !resolved.enabled) {
  throw new Error("route selection or normalization incorrect");
}
if (permit.ownerId !== " owner-1 " || zones[0] !== " north " || routes[3].id !== " winner ") {
  throw new Error("inputs were mutated");
}
(resolved as { id: string }).id = "mutated";
const resolvedAgain = resolveRoute(permit, routes);
if (resolvedAgain.id !== "winner" || resolvedAgain === resolved) throw new Error("result was not a fresh defensive copy");

const tie = resolveRoute(
  { ownerId: "o", zones: ["z"] },
  [
    { id: "first", zone: "z", priority: 3, enabled: true },
    { id: "second", zone: "z", priority: 3, enabled: true },
  ],
);
if (tie.id !== "first") throw new Error("priority tie did not use input order");

expectNoRoute(() => resolveRoute({ ownerId: " empty-owner ", zones: [] }, []), "empty-owner");
expectNoRoute(() => resolveRoute({ ownerId: "case", zones: ["North"] }, [{ id: "r", zone: "north", priority: 0, enabled: true }]), "case");
expectRangeError(() => resolveRoute({ ownerId: " ", zones: [] }, []));
expectRangeError(() => resolveRoute({ ownerId: "o", zones: [" "] }, []));
expectRangeError(() => resolveRoute({ ownerId: "o", zones: ["z"] }, [{ id: " ", zone: "z", priority: 0, enabled: false }]));
expectRangeError(() => resolveRoute({ ownerId: "o", zones: ["z"] }, [{ id: "r", zone: " ", priority: 0, enabled: true }]));
expectRangeError(() => resolveRoute({ ownerId: "o", zones: ["z"] }, [{ id: "r", zone: "z", priority: 1.5, enabled: true }]));
expectRangeError(() => resolveRoute({ ownerId: "o", zones: ["z"] }, [{ id: "r", zone: "z", priority: Infinity, enabled: true }]));
expectErrorMessage(
  () => resolveRoute(
    { ownerId: "o", zones: ["z"] },
    [
      { id: "dup", zone: "z", priority: 0, enabled: true },
      { id: " dup ", zone: "other", priority: 1, enabled: false },
    ],
  ),
  "Duplicate route ID",
);

